function starRow(score) {
  const normalized = Math.max(0,Math.min(5,Math.round(Number(score) * 2) / 2));
  const stars = [1,2,3,4,5].map(position => {
    const fill = normalized >= position ? 100 : normalized >= position - .5 ? 50 : 0;
    return `<i style="--star-fill:${fill}%" aria-hidden="true">★</i>`;
  }).join("");
  const label = state.lang === "fr" ? `${normalized.toFixed(1)} sur 5` : `${normalized.toFixed(1)} out of 5`;
  return `<span class="stars" aria-label="${label}">${stars}<small>${normalized.toFixed(1)}</small></span>`;
}
