function planImageNumber(system,item) {
  let offset = 0;
  for (const currentSystem of planSystems) {
    if (currentSystem.id === system.id) return offset + currentSystem.items.indexOf(item) + 1;
    offset += currentSystem.items.length;
  }
  return 0;
}
function planImageFor(system,item) {
  const number = String(planImageNumber(system,item)).padStart(3,"0");
  return `assets/material-placeholders/${number}.jpg`;
}
function openPlanDetail(itemIndex) {
  const system = planSystems.find(value => value.id === state.planSystem); const item = system?.items[itemIndex]; if (!system || !item) return;
  const name = item[state.lang]; const description = item[state.lang === "fr" ? "descriptionFr" : "descriptionEn"];
  const ratings = {score:item.score,environment:item.environment,health:item.health,efficiency:item.efficiency,durability:item.durability};
  ratings.overall = Math.round(((ratings.environment + ratings.health + ratings.efficiency + ratings.durability) / 4) * 2) / 2;
  const categoryLabels = planRatingCategories[system.id][state.lang];
  const fallbackImage = planSystemImages[system.id];
  qs("#detail-content").innerHTML = `<article class="plan-detail"><div class="modal-eyebrow">${system[state.lang]}</div><h2>${name}</h2><div class="plan-detail-intro"><img class="plan-detail-image" src="${planImageFor(system,item)}" data-fallback-image="${fallbackImage}" onerror="this.onerror=null;this.src=this.dataset.fallbackImage" alt="${name}"><p class="plan-short-description">${description}</p></div><div class="plan-score-layout"><section class="sustainability-panel"><span>${t("sustainabilityScore")}</span><div class="score-ring" style="--score:${ratings.score}"><div><strong>${ratings.score}</strong><small>/ 100</small></div></div></section><section class="overall-panel"><span>${t("overallRating")}</span><button type="button" class="overall-toggle" data-rating-toggle aria-expanded="false" aria-controls="plan-rating-breakdown"><span class="overall-toggle-main"><b>${starRow(ratings.overall)}</b><small>${t("ratingDetails")}</small></span><span class="rating-chevron" aria-hidden="true"><svg viewBox="0 0 20 20"><path d="m5.5 7.5 4.5 4.5 4.5-4.5"/></svg></span></button><div class="rating-breakdown" id="plan-rating-breakdown" aria-hidden="true"><div><span>${categoryLabels[0]}</span>${starRow(ratings.environment)}</div><div><span>${categoryLabels[1]}</span>${starRow(ratings.health)}</div><div><span>${categoryLabels[2]}</span>${starRow(ratings.efficiency)}</div><div><span>${categoryLabels[3]}</span>${starRow(ratings.durability)}</div></div></section></div><section class="plan-price-box"><div><span>${t("planPrice")}</span><b>${t("canadianEstimate")}</b></div><strong>${item[state.lang === "fr" ? "priceFr" : "priceEn"]}</strong><small>${t("planPriceNote")}</small></section></article>`;
  qs("#detail-modal").showModal();
}

